  const cancelledUnit = findFirstUnit(snapshot, (unit) => unit.state === "cancelled");
  if (cancelledUnit) return ok({ commands: [{ kind: "complete_run", outcome: cancelledUnit.outcome ?? { kind: "cancelled", reason: null } }] });
